import type { BlogArticleFaq } from '../../../types/blog';

export const BODY: string = "\n<p>Bulanıklaştırma mı pikselleştirme mi? İkisi de ayrıntıyı gizler ama farklı görünür ve farklı güvenlik sunar.</p>\n<p>Yanlış seçim, sansürü bozar. Hafif bulanıklık yüzü tanınır bırakır; küçük blok metni okunur bırakır.</p>\n<p>Bu yazı, iki yöntemin nasıl çalıştığını, hangisinin daha güvenli olduğunu ve ne zaman birleştirileceklerini anlatıyor.</p>\n<h2 id=\"how-each-method-works\">Her yöntem nasıl çalışır?</h2>\n<p>Bulanıklaştırma, pikselleri yumuşatır. Komşu pikseller karıştırılır; keskin kenarlar kaybolur.</p>\n<p>Pikselleştirme, görseli büyük renk bloklarına böler. Her blok, içindeki piksellerin ortalamasını alır.</p>\n<p>İki yöntem de geri alınamaz. Sansürlü kopya indirildikten sonra orijinal ayrıntı geri gelmez.</p>\n<h2 id=\"how-they-look\">Yan yana nasıl görünürler?</h2>\n<p>Bulanıklaştırma yumuşak görünür. Fotoğraf doğal durur; gizlenen alan sisli görünür.</p>\n<p>Pikselleştirme keskin görünür. Bloklar belirgindir; sansür açıkça belli olur.</p>\n<p>Görünüm, amaca bağlıdır. Doğal görünüm için bulanıklaştırma, açık sansür için pikselleştirme kullanın.</p>\n<h2 id=\"safety-comparison\">Hangi yöntem daha güvenli?</h2>\n<p>Güçlü bulanıklık ve büyük blok, ikisi de güvenlidir. Zayıf ayarlar, ikisinde de sızıntı yapar.</p>\n<p>Metin için pikselleştirme daha güvenlidir. Bulanık metin bazen okunabilir; bloklar okunamaz.</p>\n<p>Yüz için ikisi de olur. Güçlü bulanıklık ya da büyük blok, yüzü tanınmaz yapar.</p>\n<h2 id=\"hiding-faces\">Yüz gizlemek: bulanıklaştırma mı pikselleştirme mi?</h2>\n<p>Yüzler için bulanıklaştırma doğal görünür. Portrelerde yumuşak geçiş hoş durur.</p>\n<p>Pikselleştirme, yüzü açıkça sansürler. Haber ve belgesellerde bu görünüm yaygındır.</p>\n<p>Seçim, tona bağlıdır. Doğal görünüm için bulanıklaştırma, açık sansür için pikselleştirme kullanın.</p>\n<h2 id=\"hiding-text\">Metin ve sayı gizlemek: bulanıklaştırma mı pikselleştirme mi?</h2>\n<p>Metin için pikselleştirme daha güvenlidir. Bulanık harfler bazen tahmin edilebilir.</p>\n<p>Büyük blok kullanın. Harfler, blokların altında tamamen kaybolmalıdır.</p>\n<p>Gizledikten sonra metni okumaya çalışın. Okunuyorsa blokları büyütün.</p>\n<h2 id=\"license-plates\">Plakalar ve araç ayrıntıları</h2>\n<p>Plakalar için pikselleştirme kullanın. Harf ve rakamlar, bloklarla gizlenmelidir.</p>\n<p>Plakanın tamamını gizleyin. Kısmi gizleme, plakayı tahmin edilebilir bırakır.</p>\n<p>Araç rengi ve modeli de ipucu verebilir. Gerekirse aracın tamamını gizleyin.</p>\n<h2 id=\"documents-and-screens\">Belgeler, ekranlar ve evraklar</h2>\n<p>Belgelerde hassas alanları pikselleştirin. Kimlik numarası ve adres, bloklarla gizlenmelidir.</p>\n<p>Ekran görüntülerinde şifreleri pikselleştirin. Bulanık şifre bazen okunabilir.</p>\n<p>Belgenin geri kalanı okunur kalmalıdır. Yalnızca hassas alanları gizleyin.</p>\n<h2 id=\"backgrounds\">Arka planlar: bulanıklaştırmanın en iyi araç olduğu durumlar</h2>\n<p>Arka plan için bulanıklaştırma idealdir. Yumuşak arka plan, konuyu öne çıkarır.</p>\n<p>Pikselleştirme, arka planda yapay görünür. Bloklar, dikkat dağıtır.</p>\n<p>Portrelerde hafif bulanıklık kullanın. Doğal görünüm korunmalıdır.</p>\n<h2 id=\"reversibility-myths\">Sansürlü görseller geri alınabilir mi?</h2>\n<p>Efsane: sansür her zaman geri alınır. Gerçek: güçlü sansür geri alınamaz.</p>\n<p>Hafif bulanıklık, yapay zekâyla kısmen geri alınabilir. Bu yüzden güvenlik için güçlü kullanın.</p>\n<p>Orijinal dosyayı kimseyle paylaşmayın. Sansürlü kopya güvenlidir; orijinal değildir.</p>\n<h2 id=\"strength-settings\">Güç ayarları karşılaştırması</h2>\n<p>Bulanıklık gücü, yumuşaklığı belirler. Yüzde 50'nin altı, yüzü tanınır bırakır.</p>\n<p>Blok boyutu, mozaik büyüklüğünü belirler. Küçük bloklar, metni okunur bırakır.</p>\n<p>Her iki ayarı da test edin. Gizledikten sonra ayrıntıyı bulmaya çalışın; bulamıyorsanız yeterlidir.</p>\n<h2 id=\"combining-both\">Bulanıklaştırma ve pikselleştirmeyi birleştirmek</h2>\n<p>İki yöntem aynı görselde birleştirilebilir. Yüzü bulanıklaştırın, plakayı pikselleştirin.</p>\n<p>Birleştirme, her alan için en iyi yöntemi kullanmanızı sağlar. Yüz doğal, plaka güvenli olur.</p>\n<p>Sonucu kontrol edin. Her alanın gizlendiğinden emin olun.</p>\n<h2 id=\"legal-and-ethical\">Yasal ve etik notlar</h2>\n<p>Çocukların yüzlerini her zaman gizleyin. Çocuk gizliliği, en katı kuraldır.</p>\n<p>İzinsiz çekilen fotoğrafları paylaşmayın. Sansür, izinsiz paylaşımı meşru kılmaz.</p>\n<p>Yasal zorunlulukları öğrenin. Bazı ülkelerde yüz gizlemek yasal gerekliliktir.</p>\n<h2 id=\"when-neither-is-enough\">Hiçbir yöntem yetmediğinde</h2>\n<p>Bazen sansür yetmez. Fotoğrafı kırpmak, hassas alanı tamamen atar.</p>\n<p>Bazen fotoğrafı paylaşmamak gerekir. En güvenli sansür, paylaşmamaktır.</p>\n<p>Şüphede kalırsanız paylaşmayın. Gizlilik hatası geri alınamaz.</p>\n<h2 id=\"choosing-for-screenshots\">Ekran görüntüleri için seçim</h2>\n<p>Ekran görüntülerinde metin için pikselleştirme kullanın. Bulanık metin okunabilir.</p>\n<p>Ekran görüntüleri PNG ister. Kayıpsız sıkıştırma, yazıları bozmaz.</p>\n<p>Şifreleri ve kişisel bilgileri gizleyin. Ekran görüntüsü paylaşmadan önce kontrol edin.</p>\n<h2 id=\"cheat-sheet\">Hızlı karar kılavuzu</h2>\n<p>Yüz: bulanıklaştırma ya da pikselleştirme, güçlü ayar. Metin: pikselleştirme, büyük blok.</p>\n<p>Plaka: pikselleştirme, büyük blok. Arka plan: bulanıklaştırma, hafif ayar.</p>\n<p>Bu listeyi kaydedin. Her sansürde yeniden düşünmek zaman kaybıdır.</p>\n<h2 id=\"blur-vs-pixelate-social\">Sosyal medyada bulanıklaştırma ve pikselleştirme</h2>\n<p>Sosyal medyada çocuk yüzlerini gizleyin. Güçlü yöntem kullanın.</p>\n<p>Plakaları ve adresleri gizleyin. Kişisel bilgi, sosyal medyada yayılır.</p>\n<p>Paylaşmadan önce kontrol edin. Birkaç saniyelik kontrol, gizlilik hatasını önler.</p>\n<p>Özetle: metin için pikselleştirme, yüz için ikisi de olur; güç her zaman yüksek olsun. Adımlar için <a href=\"/tr/blog/gorsel-nasil-bulaniklastirilir-piksellestirilir\">Görsel bulanıklaştırma ve pikselleştirme nasıl yapılır</a> yazısına bakın; kılavuzun tamamı <a href=\"/tr/blog/gorsel-bulaniklastir-piksellestir-rehberi\">bulanıklaştırma ve pikselleştirme kılavuzunda</a>. Konum verisi için <a href=\"/tr/gorsel-metadata-kaldir\">meta veri kaldırma</a> hazırdır; araç ise <a href=\"/tr/gorsel-bulaniklastir-piksellestir\">bulanıklaştırma ve pikselleştirme</a> sayfasındadır.</p>\n";

export const FAQS: BlogArticleFaq[] = [{"question":"Yüz gizlemek için bulanıklaştırma mı pikselleştirme mi daha iyi?","answer":"İkisi de olur; seçim tona bağlıdır. Bulanıklaştırma doğal görünür, portrelerde hoş durur. Pikselleştirme açık sansür görünümü verir; haberlerde yaygındır. Güvenlik için güçlü ayar kullanın; hafif gizleme yüzü tanınır bırakır."},{"question":"Biri yapay zekâ yazılımıyla fotoğraftaki bulanıklığı kaldırabilir mi?","answer":"Hafif bulanıklık kısmen geri alınabilir; güçlü bulanıklık geri alınamaz. Bu yüzden güvenlik için güçlü bulanıklık ya da büyük bloklu pikselleştirme kullanın. Orijinal dosyayı kimseyle paylaşmayın."},{"question":"Ekran görüntüsündeki şifreyi bulanıklaştırmalı mı pikselleştirmeli miyim?","answer":"Pikselleştirin. Bulanık metin bazen okunabilir; harfler tahmin edilebilir. Büyük blok kullanın ve gizledikten sonra metni okumaya çalışın; okunuyorsa blokları büyütün."},{"question":"Gözlerin üzerine siyah bant, yüzü gizlemek için yeterli mi?","answer":"Hayır. Yüz, gözler olmadan da tanınır; çene, burun ve saç ipucu verir. Yüzün tamamını gizleyin; güçlü bulanıklık ya da büyük blok kullanın."},{"question":"Aynı görselde bulanıklaştırma ve pikselleştirmeyi birlikte kullanabilir miyim?","answer":"Evet. Yüzü bulanıklaştırın, plakayı pikselleştirin; iki yöntem aynı görselde bir arada kullanılabilir. Her alan için en iyi yöntemi seçin ve sonucu indirmeden önce kontrol edin."},{"question":"Fotoğrafı sansürlemek konum verilerini de siler mi?","answer":"Hayır, sansür EXIF verilerini silmez; konum bilgisi dosyada kalır. Konumu silmek istiyorsanız meta veri kaldırma aracını kullanın. Paylaşmadan önce konum verisini kontrol edin."}];
